package com.crm.hr.controller;
import com.crm.hr.dto.CareerEventRequest;import com.crm.hr.dto.LeaveQuotaRequest;import com.crm.hr.entity.CareerEvent;import com.crm.hr.entity.EmployeeDocument;import com.crm.hr.entity.LeaveQuota;import com.crm.hr.service.CareerEventService;import com.crm.hr.service.EmployeeDocumentService;import com.crm.hr.service.LeaveQuotaService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.List;
@RestController public class EmployeeDossierController{
 private final EmployeeDocumentService documents;private final CareerEventService career;private final LeaveQuotaService quotas;
 public EmployeeDossierController(EmployeeDocumentService d,CareerEventService c,LeaveQuotaService q){documents=d;career=c;quotas=q;}
 @GetMapping("/api/employees/{employeeId}/documents") public List<EmployeeDocument> documents(@PathVariable String employeeId,@RequestHeader(org.springframework.http.HttpHeaders.AUTHORIZATION) String authorization){return documents.list(employeeId,authorization);}
 @PostMapping(path="/api/employees/{employeeId}/documents",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED)
 public EmployeeDocument upload(@PathVariable String employeeId,@RequestParam String type,@RequestPart("file") MultipartFile file,@RequestHeader(org.springframework.http.HttpHeaders.AUTHORIZATION) String authorization){return documents.upload(employeeId,type,file,authorization);}
 @GetMapping("/api/documents/{id}/content") public ResponseEntity<byte[]> download(@PathVariable long id){EmployeeDocument metadata=documents.metadata(id);byte[] body=documents.download(id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(metadata.getMediaType())).header(HttpHeaders.CACHE_CONTROL,"no-store").header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(metadata.getName(),java.nio.charset.StandardCharsets.UTF_8).build().toString()).body(body);}
 @DeleteMapping("/api/documents/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteDocument(@PathVariable long id){documents.delete(id);}
 @GetMapping("/api/employees/{employeeId}/career-events") public List<CareerEvent> career(@PathVariable String employeeId,@RequestHeader(org.springframework.http.HttpHeaders.AUTHORIZATION) String authorization){return career.list(employeeId,authorization);}
 @PostMapping("/api/career-events") @ResponseStatus(HttpStatus.CREATED) public CareerEvent createCareer(@Valid @RequestBody CareerEventRequest request,@RequestHeader(org.springframework.http.HttpHeaders.AUTHORIZATION) String authorization){return career.create(request,authorization);}
 @DeleteMapping("/api/career-events/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteCareer(@PathVariable long id){career.delete(id);}
 @GetMapping("/api/employees/{employeeId}/leave-quotas") public List<LeaveQuota> quotas(@PathVariable String employeeId,@RequestHeader(org.springframework.http.HttpHeaders.AUTHORIZATION) String authorization){return quotas.list(employeeId,authorization);}
 @PostMapping("/api/leave-quotas") @ResponseStatus(HttpStatus.CREATED) public LeaveQuota assignQuota(@Valid @RequestBody LeaveQuotaRequest request,@RequestHeader(org.springframework.http.HttpHeaders.AUTHORIZATION) String authorization){return quotas.assign(request,authorization);}
 @DeleteMapping("/api/leave-quotas/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteQuota(@PathVariable long id){quotas.delete(id);}
}
